import { readFileSync, writeFileSync } from 'node:fs';
import { format, resolveConfig } from 'prettier';
import ts from 'typescript';
import {
  light,
  dark,
  clubReaderLight,
  clubReaderDark,
  studyLight,
  studyDark,
} from '../packages/design-tokens/src/index';
const block = (selector: string, values: Record<string, string>) =>
  selector +
  ' {\n' +
  Object.entries(values)
    .map(([key, value]) => '  --' + key + ': ' + value + ';')
    .join('\n') +
  '\n}\n';
const header =
  '/* Generated by npm run tokens:build. Edit packages/design-tokens/src/index.ts. */\n';
const outputs = {
  'packages/design-tokens/tokens.css':
    header +
    ':root {\n  color-scheme: light;\n  background-color: var(--paper);\n}\n' +
    block(':root', light) +
    '@media (prefers-color-scheme: dark) {\n' +
    '  :root:not(.light) {\n    color-scheme: dark;\n    background-color: var(--paper);\n  }\n' +
    block(':root:not(.light)', dark) +
    '}\n' +
    ':root.dark {\n  color-scheme: dark;\n  background-color: var(--paper);\n}\n' +
    block(':root.dark', dark) +
    ':root.light {\n  color-scheme: light;\n  background-color: var(--paper);\n}\n' +
    block(':root.light', light) +
    'html,\nbody {\n  background-color: var(--paper);\n}\n' +
    Object.entries(clubReaderLight)
      .map(([theme, values]) => block(`.club-reader-theme-${theme}`, values))
      .join('') +
    '@media (prefers-color-scheme: dark) {\n' +
    Object.entries(clubReaderDark)
      .map(([theme, values]) => block(`:root:not(.light) .club-reader-theme-${theme}`, values))
      .join('') +
    '}\n' +
    Object.entries(clubReaderDark)
      .map(([theme, values]) => block(`:root.dark .club-reader-theme-${theme}`, values))
      .join(''),
  'packages/design-tokens/study.css':
    header +
    '@layer base {\n' +
    '  :root[data-theme-palette="study"] {\n    color-scheme: light;\n    background-color: var(--study-paper);\n  }\n' +
    block(':root', studyLight) +
    '  :root[data-theme-palette="study"].dark {\n    color-scheme: dark;\n    background-color: var(--study-paper);\n  }\n' +
    block('.dark', studyDark) +
    '  html[data-theme-palette="study"],\n  html[data-theme-palette="study"] body {\n    background-color: var(--study-paper);\n  }\n' +
    '}\n',
};
async function main() {
  const colors = {
    light: light.paper,
    dark: dark.paper,
    studyLight: studyLight['study-paper'],
    studyDark: studyDark['study-paper'],
  };
  // Compile the dependency-free core into a local CommonJS scope, so the exact same
  // implementation runs before paint without fetching any application modules.
  const core = ts.transpileModule(
    readFileSync('packages/design-tokens/src/browser-theme-core.ts', 'utf8'),
    { compilerOptions: { target: ts.ScriptTarget.ES2020, module: ts.ModuleKind.CommonJS } },
  ).outputText;
  const bootstrap = `(() => {
    const exports = {};
    ${core}
    window.__newmaybeTheme ??= exports.createBrowserTheme(${JSON.stringify(colors)});
    window.__newmaybeTheme.start();
  })();`;
  const generatedHeader =
    '// Generated by npm run tokens:build. Edit browser-theme-core.ts or index.ts.\n';
  const generated: Record<string, string> = {
    ...outputs,
    'packages/design-tokens/src/theme-bootstrap.ts':
      generatedHeader + `export default ${JSON.stringify(bootstrap)};\n`,
  };
  for (const app of ['ai', 'club', 'studio', 'study']) {
    const path = `apps/${app}/index.html`;
    const lightColor = app === 'study' ? colors.studyLight : colors.light;
    const darkColor = app === 'study' ? colors.studyDark : colors.dark;
    generated[path] = readFileSync(path, 'utf8')
      .replace(
        /<!-- theme-meta:start -->[\s\S]*?<!-- theme-meta:end -->/,
        `<!-- theme-meta:start -->
        <!-- Generated by npm run tokens:build. -->
        <meta name="theme-color" content="${lightColor}" media="(prefers-color-scheme: light)" />
        <meta name="theme-color" content="${darkColor}" media="(prefers-color-scheme: dark)" />
        <meta name="color-scheme" content="light dark" />
        <!-- theme-meta:end -->`,
      )
      .replace(
        /<!-- theme-bootstrap:start -->[\s\S]*?<!-- theme-bootstrap:end -->/,
        `<!-- theme-bootstrap:start -->
        <!-- Generated by npm run tokens:build. Edit browser-theme-core.ts or index.ts. -->
        <script>${bootstrap}</script>
        <!-- theme-bootstrap:end -->`,
      );
  }
  for (const [path, source] of Object.entries(generated)) {
    const output = await format(source, { ...(await resolveConfig(path)), filepath: path });
    if (process.argv.includes('--check')) {
      // Git may check text out as CRLF on Windows; that is not token drift.
      if (readFileSync(path, 'utf8').replace(/\r\n/g, '\n') !== output.replace(/\r\n/g, '\n'))
        throw new Error(path + ' is stale; run npm run tokens:build');
    } else writeFileSync(path, output);
  }
}
void main();
